import java.util.*;

class Solution {
    public List<List<Integer>> palindromePairs(String[] words) {
        Map<String, Integer> index = new HashMap<>();
        for (int i = 0; i < words.length; i++) {
            index.put(words[i], i);
        }
        List<List<Integer>> answer = new ArrayList<>();
        Set<Long> seen = new HashSet<>();
        for (int i = 0; i < words.length; i++) {
            String word = words[i];
            for (int split = 0; split <= word.length(); split++) {
                String left = word.substring(0, split);
                String right = word.substring(split);
                if (isPalindrome(left)) {
                    Integer other = index.get(reverse(right));
                    if (other != null && other != i) add(answer, seen, other, i);
                }
                if (split < word.length() && isPalindrome(right)) {
                    Integer other = index.get(reverse(left));
                    if (other != null && other != i) add(answer, seen, i, other);
                }
            }
        }
        return answer;
    }

    private void add(List<List<Integer>> answer, Set<Long> seen, int first, int second) {
        long key = (((long) first) << 32) ^ second;
        if (seen.add(key)) answer.add(Arrays.asList(first, second));
    }

    private String reverse(String value) {
        return new StringBuilder(value).reverse().toString();
    }

    private boolean isPalindrome(String value) {
        int left = 0, right = value.length() - 1;
        while (left < right) {
            if (value.charAt(left++) != value.charAt(right--)) return false;
        }
        return true;
    }
}

