class Solution {
    static class Node {
        Node[] next = new Node[26];
        int wordIndex = -1;
        List<Integer> palindromeSuffixWordIds = new ArrayList<>();
    }

    public List<List<Integer>> palindromePairs(String[] words) {
        Node root = new Node();
        for (int i = 0; i < words.length; i++) {
            addWord(root, words[i], i);
        }
        List<List<Integer>> answer = new ArrayList<>();
        Set<Long> seen = new HashSet<>();
        for (int i = 0; i < words.length; i++) {
            search(root, words[i], i, answer, seen);
        }
        return answer;
    }

    private void addWord(Node root, String word, int index) {
        Node node = root;
        for (int pos = word.length() - 1; pos >= 0; pos--) {
            if (isPalindrome(word, 0, pos)) node.palindromeSuffixWordIds.add(index);
            int c = word.charAt(pos) - 'a';
            if (node.next[c] == null) node.next[c] = new Node();
            node = node.next[c];
        }
        node.wordIndex = index;
        node.palindromeSuffixWordIds.add(index);
    }

    private void search(Node root, String word, int index, List<List<Integer>> answer, Set<Long> seen) {
        Node node = root;
        for (int pos = 0; pos < word.length(); pos++) {
            if (node.wordIndex >= 0 && node.wordIndex != index && isPalindrome(word, pos, word.length() - 1)) {
                add(answer, seen, index, node.wordIndex);
            }
            int c = word.charAt(pos) - 'a';
            node = node.next[c];
            if (node == null) return;
        }
        if (node.wordIndex >= 0 && node.wordIndex != index) add(answer, seen, index, node.wordIndex);
        for (int other : node.palindromeSuffixWordIds) {
            if (other != index) add(answer, seen, index, other);
        }
    }

    private void add(List<List<Integer>> answer, Set<Long> seen, int first, int second) {
        long key = (((long) first) << 32) ^ second;
        if (seen.add(key)) answer.add(Arrays.asList(first, second));
    }

    private boolean isPalindrome(String s, int left, int right) {
        while (left < right) {
            if (s.charAt(left++) != s.charAt(right--)) return false;
        }
        return true;
    }
}

