    static class SplitPalindromes {
        boolean[] prefixPal;
        boolean[] suffixPal;
    }

    private SplitPalindromes buildPalindromeTable(String word) {
        int m = word.length();
        boolean[][] pal = new boolean[m][m];
        for (int len = 1; len <= m; len++) {
            for (int left = 0; left + len <= m; left++) {
                int right = left + len - 1;
                pal[left][right] = word.charAt(left) == word.charAt(right) && (len <= 2 || pal[left + 1][right - 1]);
            }
        }
        SplitPalindromes split = new SplitPalindromes();
        split.prefixPal = new boolean[m + 1];
        split.suffixPal = new boolean[m + 1];
        split.prefixPal[0] = true;
        split.suffixPal[m] = true;
        for (int end = 1; end <= m; end++) split.prefixPal[end] = pal[0][end - 1];
        for (int start = 0; start < m; start++) split.suffixPal[start] = pal[start][m - 1];
        return split;
    }

