class Solution {
    public List<List<Integer>> palindromePairs(String[] words) {
        Map<String, Integer> index = new HashMap<>();
        for (int i = 0; i < words.length; i++) index.put(words[i], i);
        List<List<Integer>> answer = new ArrayList<>();
        Set<Long> seen = new HashSet<>();
        for (int i = 0; i < words.length; i++) {
            String word = words[i];
            boolean[] prefixPal = prefixPalindrome(word);
            boolean[] suffixPal = suffixPalindrome(word);
            for (int split = 0; split <= word.length(); split++) {
                if (prefixPal[split]) {
                    Integer other = index.get(reverse(word.substring(split)));
                    if (other != null && other != i) add(answer, seen, other, i);
                }
                if (split < word.length() && suffixPal[split]) {
                    Integer other = index.get(reverse(word.substring(0, split)));
                    if (other != null && other != i) add(answer, seen, i, other);
                }
            }
        }
        return answer;
    }

    private boolean[] suffixPalindrome(String s) {
        String reversed = reverse(s);
        boolean[] prefixOfReverse = prefixPalindrome(reversed);
        boolean[] suffix = new boolean[s.length() + 1];
        for (int start = 0; start <= s.length(); start++) {
            suffix[start] = prefixOfReverse[s.length() - start];
        }
        return suffix;
    }

    private boolean[] prefixPalindrome(String s) {
        int n = s.length();
        boolean[] prefix = new boolean[n + 1];
        prefix[0] = true;
        int[] odd = manacherOdd(s);
        int[] even = manacherEven(s);
        for (int center = 0; center < n; center++) {
            if (center - odd[center] + 1 == 0) prefix[center + odd[center]] = true;
            if (center - even[center] == 0) prefix[center + even[center]] = true;
        }
        return prefix;
    }

    private int[] manacherOdd(String s) {
        int n = s.length();
        int[] radius = new int[n];
        int left = 0, right = -1;
        for (int i = 0; i < n; i++) {
            int k = i > right ? 1 : Math.min(radius[left + right - i], right - i + 1);
            while (i - k >= 0 && i + k < n && s.charAt(i - k) == s.charAt(i + k)) k++;
            radius[i] = k;
            if (i + k - 1 > right) {
                left = i - k + 1;
                right = i + k - 1;
            }
        }
        return radius;
    }

    private int[] manacherEven(String s) {
        int n = s.length();
        int[] radius = new int[n];
        int left = 0, right = -1;
        for (int i = 0; i < n; i++) {
            int k = i > right ? 0 : Math.min(radius[left + right - i + 1], right - i + 1);
            while (i - k - 1 >= 0 && i + k < n && s.charAt(i - k - 1) == s.charAt(i + k)) k++;
            radius[i] = k;
            if (i + k - 1 > right) {
                left = i - k;
                right = i + k - 1;
            }
        }
        return radius;
    }

