import java.util.*;

class Solution {
    public List<List<Integer>> palindromePairs(String[] words) {
        Map<String, Integer> index = new HashMap<>();
        Set<Integer> lengths = new HashSet<>();
        for (int i = 0; i < words.length; i++) {
            index.put(words[i], i);
            lengths.add(words[i].length());
        }
        List<List<Integer>> answer = new ArrayList<>();
        Set<Long> seen = new HashSet<>();
        for (int i = 0; i < words.length; i++) {
            String word = words[i];
            for (int len : lengths) {
                if (len > word.length()) continue;
                String beforeNeed = reverseSlice(word, word.length() - len, word.length());
                Integer before = index.get(beforeNeed);
                if (before != null && before != i && isPalindrome(word, 0, word.length() - len - 1)) {
                    add(answer, seen, before, i);
                }
                if (len < word.length()) {
                    String afterNeed = reverseSlice(word, 0, len);
                    Integer after = index.get(afterNeed);
                    if (after != null && after != i && isPalindrome(word, len, word.length() - 1)) {
                        add(answer, seen, i, after);
                    }
                }
            }
        }
        return answer;
    }

    private String reverseSlice(String word, int start, int end) {
        StringBuilder builder = new StringBuilder(end - start);
        for (int i = end - 1; i >= start; i--) builder.append(word.charAt(i));
        return builder.toString();
    }

    private boolean isPalindrome(String word, int left, int right) {
        while (left < right) {
            if (word.charAt(left++) != word.charAt(right--)) return false;
        }
        return true;
    }

    private void add(List<List<Integer>> answer, Set<Long> seen, int first, int second) {
        long key = (((long) first) << 32) ^ second;
        if (seen.add(key)) answer.add(Arrays.asList(first, second));
    }
